/**
 * DAMVERSE - Power Generation & Electrical Grid Simulation
 * Calculates hydroelectric turbine output, solar farm generation, BESS storage, and grid stability.
 */

import { DamSimulationState, TurbineUnit } from '../types/game';
import { calculateHead } from './waterSimulation';

const GRAVITY = 9.81; // m/s²
const WATER_DENSITY = 1000; // kg/m³

/**
 * Calculates power generated by a single Francis turbine in Megawatts (MW).
 * P (MW) = (eta * rho * g * Q * H) / 1,000,000
 */
export function calculateTurbineMW(turbine: TurbineUnit, head: number, hasCeramicBlades: boolean): number {
  if (!turbine.active || turbine.flowRate <= 0 || head <= 1.0) return 0;
  // Efficiency curve: peaks at ~85% throttle
  const throttleFrac = turbine.throttlePercent / 100;
  let efficiency = 0.88 - Math.pow(throttleFrac - 0.85, 2) * 0.2;
  if (turbine.upgraded) efficiency += 0.04;
  if (hasCeramicBlades) efficiency += 0.03;
  // Wear reduces efficiency
  const wearPenalty = (turbine.wearPercent / 100) * 0.12;
  efficiency = Math.max(0.6, efficiency - wearPenalty);

  const powerWatts = efficiency * WATER_DENSITY * GRAVITY * turbine.flowRate * head;
  return Math.min(65, powerWatts / 1_000_000);
}

/**
 * Calculates realistic city and industrial electricity demand based on 24h clock.
 */
export function calculateGridDemand(timeOfDay: number): { cityDemand: number; industrialDemand: number; ruralDemand: number; totalDemand: number } {
  // Diurnal curve
  // Midnight to 6am: low demand (~55 MW)
  // 7am to 12pm: morning ramp
  // 1pm to 5pm: afternoon industrial/commercial peak (~115 MW)
  // 7pm to 10pm: evening residential peak (~125 MW)
  const hour = timeOfDay % 24;

  let cityBase = 60;
  if (hour >= 6 && hour < 12) {
    cityBase = 75 + Math.sin(((hour - 6) / 6) * Math.PI) * 20;
  } else if (hour >= 12 && hour < 18) {
    cityBase = 85 + Math.sin(((hour - 12) / 6) * Math.PI) * 15;
  } else if (hour >= 18 && hour < 23) {
    cityBase = 95 + Math.sin(((hour - 18) / 5) * Math.PI) * 25;
  } else {
    cityBase = 50 + (1 - hour / 6) * 10;
  }

  // Industrial Demand: Heavy between 8am and 6pm
  let industrialDemand = 25;
  if (hour >= 8 && hour <= 18) {
    industrialDemand = 65 + Math.sin(((hour - 8) / 10) * Math.PI) * 15;
  }

  // Rural demand: consistent 15 MW
  const ruralDemand = 15;
  const totalDemand = Math.round(cityBase + industrialDemand + ruralDemand);

  return {
    cityDemand: Math.round(cityBase),
    industrialDemand: Math.round(industrialDemand),
    ruralDemand,
    totalDemand,
  };
}

/**
 * Runs one time step of the power generation & grid simulation.
 */
export function stepPowerSimulation(
  state: DamSimulationState,
  dt: number,
  hasSolarFarm: boolean,
  hasBessBattery: boolean,
  hasCeramicBlades: boolean
): Partial<DamSimulationState> {
  const head = calculateHead(state.reservoirLevel);

  // 1. Calculate each turbine's MW and update wear
  let hydroGenerationMW = 0;
  const updatedTurbines = state.turbines.map((t) => {
    const mw = calculateTurbineMW(t, head, hasCeramicBlades);
    hydroGenerationMW += mw;

    // Turbine wear accumulates while active
    let newWear = t.wearPercent;
    if (t.active && mw > 0) {
      const wearRate = hasCeramicBlades ? 0.001 : 0.0025;
      newWear = Math.min(100, newWear + wearRate * dt);
    }
    return { ...t, powerMW: Math.round(mw * 10) / 10, wearPercent: newWear };
  });

  // 2. Solar Farm Generation (0 to 30 MW, daytime peak around 12:00)
  let solarGenerationMW = 0;
  if (hasSolarFarm) {
    const hour = state.timeOfDay % 24;
    if (hour >= 7 && hour <= 18) {
      const sunFactor = Math.sin(((hour - 7) / 11) * Math.PI);
      const cloudFactor = Math.max(0.15, 1 - state.rainIntensity * 0.85);
      solarGenerationMW = Math.round(30 * sunFactor * cloudFactor * 10) / 10;
    }
  }

  // 3. Grid Demand calculation
  const demand = calculateGridDemand(state.timeOfDay);

  // 4. BESS Battery charge/discharge logic
  let batteryStorage = state.batteryStorageMWh;
  let batteryDischargeMW = 0;
  const rawSupply = hydroGenerationMW + solarGenerationMW;

  if (hasBessBattery) {
    const powerSurplus = rawSupply - demand.totalDemand;
    if (powerSurplus > 0) {
      // Charge battery
      const chargeRate = Math.min(powerSurplus, 25); // max 25 MW charge
      const energyAdded = (chargeRate * dt) / 3600;
      batteryStorage = Math.min(state.batteryCapacityMWh, batteryStorage + energyAdded);
    } else if (powerSurplus < 0 && batteryStorage > 0.5) {
      // Discharge battery to cover deficit
      const needed = Math.abs(powerSurplus);
      const dischargeRate = Math.min(needed, 25, batteryStorage * 2);
      batteryDischargeMW = dischargeRate;
      const energyDrawn = (dischargeRate * dt) / 3600;
      batteryStorage = Math.max(0, batteryStorage - energyDrawn);
    }
  }

  const totalAvailablePowerMW = hydroGenerationMW + solarGenerationMW + batteryDischargeMW;

  // 5. Grid Frequency & Stability
  const supplyRatio = totalAvailablePowerMW / Math.max(1, demand.totalDemand);
  let gridFrequencyHz = 50.0 + (supplyRatio - 1.0) * 1.8;
  gridFrequencyHz = Math.max(46.0, Math.min(53.0, gridFrequencyHz));

  const stability = Math.max(0, Math.min(100, 100 - Math.abs(1.0 - supplyRatio) * 110));
  const isBlackout = supplyRatio < 0.65;

  // 6. Cumulative delivered energy
  const deliveredMW = isBlackout ? 0 : Math.min(totalAvailablePowerMW, demand.totalDemand);
  const deliveredMWh = (deliveredMW * dt) / 3600;

  return {
    turbines: updatedTurbines,
    totalGenerationMW: Math.round(hydroGenerationMW * 10) / 10,
    solarGenerationMW,
    batteryDischargeMW: Math.round(batteryDischargeMW * 10) / 10,
    totalAvailablePowerMW: Math.round(totalAvailablePowerMW * 10) / 10,
    gridDemandMW: demand.totalDemand,
    baseCityDemandMW: demand.cityDemand,
    industrialDemandMW: demand.industrialDemand,
    ruralDemandMW: demand.ruralDemand,
    gridFrequencyHz: Math.round(gridFrequencyHz * 100) / 100,
    gridStability: Math.round(stability),
    isBlackout,
    batteryStorageMWh: Math.round(batteryStorage * 10) / 10,
    totalEnergyDeliveredMWh: state.totalEnergyDeliveredMWh + deliveredMWh,
  };
}
